class Graph {
  int vertices;
  List<List<int>> adj;
  Graph(this.vertices) {
    adj = List.generate(vertices, (_) => []);
  }
  void addEdge(int u, int v) {
    adj[u].add(v);
  }

  void topologicalSort() {
    List<int> inDegree = List.filled(vertices, 0);
    for (int u = 0; u < vertices; u++) {
      for (int v in adj[u]) {
        inDegree[v]++;
      }
    }

    List<int> queue = [];
    for (int i = 0; i < vertices; i++) {
      if (inDegree[i] == 0) {
        queue.add(i);
      }
    }

    int cnt = 0;
    List<int> topOrder = [];

    while (queue.isNotEmpty) {
      int u = queue.removeAt(0); // or use a real queue
      topOrder.add(u);

      for (int v in adj[u]) {
        if (--inDegree[v] == 0) {
          queue.add(v);
        }
      }
      cnt++;
    }

    if (cnt != vertices) {
      print("Graph contains a cycle, topological sort not possible.");
      return;
    }

    print("Topological Sort:");
    for (int i in topOrder) {
      print(i);
    }
  }
}
```
